import{_ as a,o as e,c as s,a2 as t}from"./chunks/framework.CCCdsIgc.js";const k=JSON.parse('{"title":"装到员工电脑","description":"","frontmatter":{},"headers":[],"relativePath":"admin/rollout.md","filePath":"admin/rollout.md"}'),l={name:"admin/rollout.md"};function o(n,i,r,d,h,p){return e(),s("div",null,[...i[0]||(i[0]=[t('<h1 id="装到员工电脑" tabindex="-1">装到员工电脑 <a class="header-anchor" href="#装到员工电脑" aria-label="Permalink to &quot;装到员工电脑&quot;">​</a></h1><h2 id="打包" tabindex="-1">打包 <a class="header-anchor" href="#打包" aria-label="Permalink to &quot;打包&quot;">​</a></h2><p>在打包用的 Windows 电脑上，进入 <code>client</code> 目录：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy Bypass </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">scripts\\publish-client.ps1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre></div><p>生成 <code>client\\dist\\FlyknitBuddy-0.3.0.zip</code>，里面有员工端、命令行 <code>flyknit</code>、更新器、运维代理和安装程序。版本号会编进程序，以它为准。</p><h2 id="发布" tabindex="-1">发布 <a class="header-anchor" href="#发布" aria-label="Permalink to &quot;发布&quot;">​</a></h2><p>管理后台「<strong>员工端版本</strong>」：上传 zip，版本号填同一个。上传后先是「未发布」，确认无误再点「<strong>发布</strong>」。</p><h2 id="安装-推荐-安装程序" tabindex="-1">安装（推荐：安装程序） <a class="header-anchor" href="#安装-推荐-安装程序" aria-label="Permalink to &quot;安装（推荐：安装程序）&quot;">​</a></h2><ol><li>同一页点「<strong>下载员工端安装包</strong>」，格式选「安装程序 .exe」，可以起个名字（比如「三车间」）；</li><li>把 <code>FlyknitBuddy-Setup-x.y.z.exe</code> 拷到员工电脑双击，输入一次管理员密码。安装程序会： <ul><li>把员工端装到 <code>C:\\Program Files\\FlyknitBuddy</code>，建快捷方式，把命令行 <code>flyknit</code> 加入系统 PATH；</li><li>装好运维代理（Windows 服务，负责以后的自动升级），用安装包里的凭证注册，不用填注册密钥；</li></ul></li><li>员工登录：加了域的电脑点「授权登录」，没加域的输入 Windows 账号和开机密码。</li></ol><p>批量安装：<code>FlyknitBuddy-Setup-x.y.z.exe /S</code> 静默安装，可以放进组策略启动脚本或 SCCM。</p><p>每下载一次安装包生成一张安装凭证，「已下载的安装包」里能看到每个包登录了几台电脑；包外泄了点「停用」，已登录的电脑不受影响。</p><h2 id="自动升级" tabindex="-1">自动升级 <a class="header-anchor" href="#自动升级" aria-label="Permalink to &quot;自动升级&quot;">​</a></h2><p>发布新版本后，员工电脑定时检查、后台下载并校验；员工点「重启升级」或关掉程序后自动换好。替换失败会自动回滚到旧版本。</p><h2 id="协议与隐私" tabindex="-1">协议与隐私 <a class="header-anchor" href="#协议与隐私" aria-label="Permalink to &quot;协议与隐私&quot;">​</a></h2><p>《用户协议》《隐私政策》有一份按本系统实际数据处理方式写的默认文本，在管理后台「协议与隐私」修改。改完后员工下次登录要同意新版本。建议请法务看一遍再发布。</p>',15)])])}const u=a(l,[["render",o]]);export{k as __pageData,u as default};
